  if (game.phase !== PHASE_OVER) {
    // Fallback: soften the rival to 1 life and land any attack through the rules.
    game.rival.life = 1;
    const any = game.player.hand.findIndex((c) => c.kind === KIND_ATTACK && c.cost <= game.player.ember);
